import csv
import requests

def check_account_status(csv_file):
    with open(csv_file, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            username = row['username']
            password = row['password']

            # Log in and check status
            response = requests.post(
                'https://admin.internal.example.com/api/login',
                data={'user': username, 'pass': password}
            )

            if response.status_code == 200:
                status_resp = requests.get(
                    'https://admin.internal.example.com/api/account_status',
                    headers={'Authorization': f'Bearer {response.json()["token"]}'}
                )
                print(f"{username}: {status_resp.json()['status']}")
            else:
                print(f"{username}: Login failed")

if __name__ == '__main__':
    check_account_status('credentials.csv')
